#include <iostream>
using namespace std;

int main() {
    unsigned long long x, y;
    cin >> x >> y;

    if (x <= 1) {
        if (x == y) {
            cout << "YES\n0";
        } else {
            cout << "NO";
        }
        return 0;
    }

    unsigned long long value = y;
    long long exponent = 0;

    while (value > 1 && value % x == 0) {
        value /= x;
        ++exponent;
    }

    if (value == 1) {
        cout << "YES\n" << exponent - 1;
    } else {
        cout << "NO";
    }

    return 0;
}

